#!/bin/sh
# Runs mtprotoproxy with config.py generated by the gateway (users = MTPROXY_USERS, set once for
# all MTProxy implementations). Listens on 127.0.0.1 only; the gateway forwards authenticated
# Telegram clients from the public port (MTPROTOPROXY_PORT) with a PROXY v2 header.
# Restarts mtprotoproxy whenever the gateway rewrites the config.
DIR=/etc/mtprotoproxy
CONF=$DIR/config.py
NAME=mtprotoproxy
. /opt/sg-run.sh
run_supervised python3 -u /opt/mtprotoproxy/mtprotoproxy.py "$CONF"
